inline int checks = 0;
inline void check(bool ok, const char* expression, int line) {
    ++checks;
    if (!ok) {
        std::cerr << "line " << line << ": " << expression << '\n';
        std::exit(1);
    }
}
#define CHECK(...) check((__VA_ARGS__), #__VA_ARGS__, __LINE__)
